import unittest
from candidate import common
from unittest.mock import patch

class TestCommonElements(unittest.TestCase):
    @patch('builtins.print')
    def test_common_unique_sorted(self, mock_print):
        self.assertEqual(common([1, 4, 3, 34, 653, 2, 5], [5, 7, 1, 5, 653, 121]), [1, 5, 653])
        mock_print.assert_not_called()

    def test_common_no_common_elements(self):
        self.assertEqual(common([1, 2, 3], [4, 5, 6]), [])

    def test_common_all_elements_equal(self):
        self.assertEqual(common([1, 1, 1], [1, 1]), [1])

    def test_common_empty_lists(self):
        self.assertEqual(common([], [1, 2, 3]), [])

    def test_common_one_list_empty(self):
        self.assertEqual(common([1, 2, 3], [], True), [])

    def test_common_both_empty_lists(self):
        self.assertEqual(common([], [], True), [])

    def test_common_all_different_elements(self):
        self.assertEqual(common([1, 2, 3], [4, 5, 6]), [])

    def test_common_with_none(self):
        self.assertRaises(TypeError, common, [None], [1, 2, 3])

    def test_common_with_none_in_middle(self):
        self.assertRaises(TypeError, common, [1, None, 2], [1, 2, 3])

    def test_common_with_none_all(self):
        self.assertEqual(common([1, None, 2], [1, 2, 3]), [1, 2])

    def test_common_large_datasets(self):
        large_list1 = list(range(1000)) + [999]
        large_list2 = list(range(500, 1500))
        result = common(large_list1, large_list2)
        self.assertEqual(len(result), 499)
        self.assertEqual(result, list(range(500, 999)))

    def test_common_with_duplicates(self):
        self.assertEqual(common([1, 1, 2, 3, 3, 4], [2, 3, 3, 4, 5]), [2, 3, 4])

    def test_common_with_mixed_data_types(self):
        self.assertRaises(TypeError, common, [1, 2, '3'], [1, 2, '3'])

    def test_common_with_case_sensitivity(self):
        self.assertEqual(common([1, 2, 'Three'], [1, 2, 'three']), [1, 2])

if __name__ == '__main__':
    unittest.main()
